# --- AUTO-SETUP ENVIRONMENT ---
def _venv_python_path(venv_path: Path) -> Path:
    return venv_path / ("Scripts/python.exe" if os.name == "nt" else "bin/python")

def _venv_is_healthy(venv_path: Path) -> bool:
    py = _venv_python_path(venv_path)
    cfg = venv_path / "pyvenv.cfg"
    if not py.exists() or not cfg.exists():
        return False

    try:
        cfg_text = cfg.read_text(encoding="utf-8", errors="ignore")
        home_match = re.search(r"^home\s*=\s*(.+)$", cfg_text, re.MULTILINE)
        exe_match = re.search(r"^executable\s*=\s*(.+)$", cfg_text, re.MULTILINE)
        base_home = Path(home_match.group(1).strip()) if home_match else None
        base_exe = Path(exe_match.group(1).strip()) if exe_match else None
        if base_home and not base_home.exists():
            return False
        if base_exe and not base_exe.exists():
            return False
    except OSError:
        return False

    try:
        probe = subprocess.run(
            [str(py), "-c", "import sys; print(sys.executable)"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            timeout=20,
        )
        return probe.returncode == 0
    except Exception:
        return False

def _create_venv(venv_path: Path, required_pkgs):
    py = _venv_python_path(venv_path)
    print("[*] Creazione ambiente virtuale...")
    subprocess.run([sys.executable, "-m", "venv", str(venv_path)], check=True)
    subprocess.run([str(py), "-m", "pip", "install", "--upgrade", "pip"], check=True)
    print("[*] Installazione dipendenze Python (incluso Playwright)...")
    subprocess.run([str(py), "-m", "pip", "install", *required_pkgs], check=True)
    print("[*] Installazione browser invisibile...")
    subprocess.run([str(py), "-m", "playwright", "install", "chromium"], check=True)
    return py

def _sync_venv_packages(py_path: Path, required_pkgs):
    print("[*] Verifica/allineamento dipendenze nella .venv...")
    subprocess.run([str(py_path), "-m", "pip", "install", "--upgrade", "pip"], check=True)
    subprocess.run([str(py_path), "-m", "pip", "install", *required_pkgs], check=True)
    subprocess.run([str(py_path), "-m", "playwright", "install", "chromium"], check=True)

def setup_env():
    script_path = Path(__file__).resolve()
    venv_path = script_path.parent / ".venv"
    py = _venv_python_path(venv_path)

    current_venv = os.environ.get("VIRTUAL_ENV", "")
    try:
        if Path(sys.executable).resolve() == py.resolve():
            return
    except Exception:
        pass
    if current_venv:
        try:
            if (
                Path(current_venv).resolve() == venv_path.resolve() and
                Path(sys.executable).resolve() == py.resolve()
            ):
                return
        except Exception:
            pass

    required_pkgs = [
        "flask", "requests", "phonenumbers", "telethon", "fpdf2", "bs4",
        "dnspython", "python-whois", "lxml", "pycountry", "playwright", "greenlet",
        "holehe", "ignorant", "trio", "httpx", "h2", "opencv-python-headless", "numpy",
        "exifread", "imageio-ffmpeg", "cryptography"
    ]

    if not venv_path.exists():
        print("[*] Init CSCORZA IntelOSINT v.1...")
        try:
            py = _create_venv(venv_path, required_pkgs)
            _sync_venv_packages(py, required_pkgs)
            print("[*] Setup completato con successo!")
        except Exception as e:
            print(f"[!] Setup Error: {e}")
            raise RuntimeError("Setup venv fallito") from e
    else:
        try:
            if not _venv_is_healthy(venv_path):
                print("[*] Ambiente virtuale non valido o collegato a un Python non piu disponibile. Ricreo la venv...")
                shutil.rmtree(venv_path, ignore_errors=True)
                py = _create_venv(venv_path, required_pkgs)
            _sync_venv_packages(py, required_pkgs)
        except Exception as e:
            print(f"[!] Setup deps error: {e}")
            raise RuntimeError("Allineamento dipendenze venv fallito") from e

    try:
        env = os.environ.copy()
        env["INTELOSINT_VENV_BOOTSTRAPPED"] = "1"
        rc = subprocess.call([str(py), str(script_path)], env=env, cwd=str(script_path.parent))
        sys.exit(rc)
    except OSError as e:
        print(f"[!] Impossibile riavviare con la venv: {e}")
        raise

if __name__ == "__main__" and os.environ.get("INTELOSINT_VENV_BOOTSTRAPPED") != "1":
    setup_env()

def _install_python_package(pkg_name: str) -> bool:
    try:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "--upgrade", "pip", pkg_name],
            stdout=sys.stdout,
            stderr=sys.stderr,
            timeout=120,
        )
        return True
    except Exception:
        return False


def _bootstrap_dependencies():
    required_modules = [
        ("flask", "flask"),
        ("requests", "requests"),
        ("phonenumbers", "phonenumbers"),
        ("dns", "dnspython"),
        ("telethon", "telethon"),
        ("bs4", "bs4"),
        ("whois", "python-whois"),
        ("pycountry", "pycountry"),
        ("fpdf", "fpdf2"),
        ("numpy", "numpy"),
        ("exifread", "exifread"),
        ("imageio_ffmpeg", "imageio-ffmpeg"),
        ("cryptography", "cryptography"),
        ("keyring", "keyring"),
    ]
    optional_modules = [
        ("playwright", "playwright"),
        ("greenlet", "greenlet"),
        ("insightface", "insightface"),
    ]
    ok = True
    installed_any = False
    optional_ok = True
    for module_name, package_name in required_modules:
        try:
            importlib.import_module(module_name)
        except ModuleNotFoundError:
            print(f"[*] Modulo mancante: {module_name} -> installo {package_name}...")
            if not _install_python_package(package_name):
                print(f"[!] Errore installazione {package_name}")
                ok = False
                continue
            installed_any = True
            importlib.invalidate_caches()
            try:
                importlib.import_module(module_name)
            except Exception as e:
                print(f"[!] Installato {package_name} ma import ancora fallito per {module_name}: {e}")
                ok = False
            continue
        except Exception as e:
            if module_name == "playwright" and "_greenlet" in str(e):
                print("[*] Errore su playwright/_greenlet, provo reinstallazione greenlet...")
                _install_python_package("greenlet")
            if module_name == "greenlet" and "_greenlet" in str(e):
                print("[*] Errore critico su greenlet, provo reinstallazione...")
                _install_python_package("greenlet")
            try:
                importlib.import_module(module_name)
            except Exception as e2:
                print(f"[!] Import errore per {module_name} dopo reinstall: {e2}")
                ok = False
            continue
    for module_name, package_name in optional_modules:
        try:
            importlib.import_module(module_name)
        except ModuleNotFoundError:
            if module_name == "insightface":
                print("[!] Modulo opzionale mancante: insightface (Face Recognition avanzato disattivato, fallback OpenCV attivo).")
                if os.name == "nt":
                    print("[!] Motivo comune su Windows: insightface richiede build native (Microsoft Visual C++ 14+).")
                    print("[!] Come risolvere su Windows:")
                    print("    1) Installa Microsoft C++ Build Tools: https://visualstudio.microsoft.com/visual-cpp-build-tools/")
                    print("    2) Riavvia terminale e aggiorna pip nella venv.")
                    print("    3) Esegui: .\\.venv\\Scripts\\python.exe -m pip install insightface onnxruntime")
                else:
                    print("[!] Su Linux/macOS verifica toolchain di build e dipendenze native, poi reinstalla insightface.")
            else:
                print(f"[!] Modulo opzionale mancante: {module_name} (Playwright disattivato): {module_name} non installato.")
            optional_ok = False
            continue
        except Exception as e:
            if module_name == "playwright" and "_greenlet" in str(e):
                print("[*] Errore su playwright/_greenlet, provo reinstallazione greenlet...")
                if not _install_python_package("greenlet"):
                    optional_ok = False
                    continue
                try:
                    importlib.import_module(module_name)
                    continue
                except Exception as e2:
                    print(f"[!] Import errore per {module_name} dopo reinstall: {e2}")
                    optional_ok = False
                    continue
            if module_name == "greenlet" and "_greenlet" in str(e):
                print("[*] Errore critico su greenlet, provo reinstallazione...")
                if not _install_python_package("greenlet"):
                    optional_ok = False
                    continue
                try:
                    importlib.import_module(module_name)
                    continue
                except Exception as e2:
                    print(f"[!] Import errore per greenlet dopo reinstall: {e2}")
                    optional_ok = False
                    continue
            print(f"[!] Modulo opzionale non disponibile: {module_name} ({e})")
            optional_ok = False
    globals()["PLAYWRIGHT_OPTIONAL_OK"] = optional_ok

    # Se sono stati installati pacchetti durante il bootstrap, riavviamo il processo
    # per evitare stati d'import parziali nello stesso interpreter.
    if ok and installed_any and os.environ.get("INTELOSINT_BOOTSTRAP_RESTARTED") != "1":
        print("[*] Dipendenze installate. Riavvio automatico dell'app...")
        os.environ["INTELOSINT_BOOTSTRAP_RESTARTED"] = "1"
        os.execv(sys.executable, [sys.executable, str(Path(__file__).resolve())])

    return ok


if not _bootstrap_dependencies():
    raise RuntimeError("Impossibile avviare l'app: alcune dipendenze non sono state installate.")

