# --- ASYNC SETUP ---
telethon_loop = None
_telethon_thread = None
_telethon_loop_lock = threading.Lock()

def _start_background_loop(loop):
    asyncio.set_event_loop(loop)
    loop.run_forever()

def get_telethon_loop():
    global telethon_loop, _telethon_thread
    if telethon_loop is not None and _telethon_thread is not None and _telethon_thread.is_alive():
        return telethon_loop
    with _telethon_loop_lock:
        if telethon_loop is None or _telethon_thread is None or not _telethon_thread.is_alive():
            telethon_loop = asyncio.new_event_loop()
            _telethon_thread = threading.Thread(
                target=_start_background_loop,
                args=(telethon_loop,),
                daemon=True
            )
            _telethon_thread.start()
    return telethon_loop

def run_async(coro):
    loop = get_telethon_loop()
    return asyncio.run_coroutine_threadsafe(coro, loop).result()

