def _load_local_env_file():
    env_path = Path(__file__).resolve().parent / ".env"
    if not env_path.exists():
        return
    try:
        for raw_line in env_path.read_text(encoding="utf-8").splitlines():
            line = raw_line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            key, value = line.split("=", 1)
            key = key.strip()
            value = value.strip().strip('"').strip("'")
            if key and key not in os.environ:
                os.environ[key] = value
    except Exception:
        print("[!] File .env presente ma non leggibile. Verifica permessi e formato.")


def _read_env_file_values(env_path: Path) -> dict:
    values = {}
    if not env_path.exists():
        return values
    try:
        for raw_line in env_path.read_text(encoding="utf-8").splitlines():
            line = raw_line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            key, value = line.split("=", 1)
            key = key.strip()
            value = value.strip().strip('"').strip("'")
            if key:
                values[key] = value
    except Exception:
        print("[!] File .env presente ma non leggibile. Verifica permessi e formato.")
    return values


def _is_valid_fernet_key(raw_value: str) -> bool:
    if not Fernet:
        return False
    try:
        Fernet(raw_value.encode("utf-8"))
        return True
    except Exception:
        return False


def _bootstrap_tokens():
    env_path = Path(__file__).resolve().parent / ".env"
    env_values = _read_env_file_values(env_path)

    admin_token = (os.environ.get("INTELOSINT_ADMIN_TOKEN") or env_values.get("INTELOSINT_ADMIN_TOKEN") or "").strip()
    if not admin_token:
        admin_token = os.urandom(32).hex()
    elif len(admin_token) < 24:
        admin_token = admin_token + os.urandom(16).hex()

    cred_key = (os.environ.get("INTELOSINT_CRED_KEY") or env_values.get("INTELOSINT_CRED_KEY") or "").strip()
    if not _is_valid_fernet_key(cred_key):
        if Fernet is None:
            raise RuntimeError("Dipendenza cryptography non disponibile: impossibile gestire INTELOSINT_CRED_KEY.")
        cred_key = Fernet.generate_key().decode("utf-8")

    os.environ["INTELOSINT_ADMIN_TOKEN"] = admin_token
    os.environ["INTELOSINT_CRED_KEY"] = cred_key
    env_values["INTELOSINT_ADMIN_TOKEN"] = admin_token
    env_values["INTELOSINT_CRED_KEY"] = cred_key

    try:
        env_lines = [f"{k}={v}" for k, v in env_values.items()]
        env_path.write_text("\n".join(env_lines) + "\n", encoding="utf-8")
    except Exception:
        print(f"[!] Impossibile scrivere o aggiornare il file {env_path}.")


