RATE_LIMIT_BUCKETS = {}
RATE_LIMIT_LOCK = threading.Lock()
TG_SESSION_KEYRING_SERVICE = "IntelOSINT"
TG_SESSION_KEYRING_USER = "telegram_session"


def _credential_master_key():
    machine_id = "|".join([
        socket.gethostname(),
        str(uuid.getnode()),
        str(Path.home()),
        os.environ.get("USERNAME", ""),
        os.environ.get("USER", "")
    ])
    return hashlib.pbkdf2_hmac(
        "sha256",
        machine_id.encode("utf-8", errors="ignore"),
        CRED_STORE_SALT.encode("utf-8", errors="ignore"),
        160_000,
        dklen=32
    )


def _fernet_key():
    return INTELOSINT_CRED_KEY.encode("utf-8")


def _cred_xor_mask(key: bytes, nonce: bytes, length: int) -> bytes:
    out = bytearray()
    block_index = 0
    while len(out) < length:
        seed = key + nonce + block_index.to_bytes(4, "big", signed=False)
        out.extend(hashlib.sha256(seed).digest())
        block_index += 1
    return bytes(out[:length])


def _encrypt_creds(payload):
    raw = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    token = Fernet(_fernet_key()).encrypt(raw).decode("ascii")
    return {"__cred_store": CRED_STORE_TAG_V2, "token": token}


def _decrypt_creds(record):
    if not isinstance(record, dict):
        return None
    if record.get("__cred_store") == CRED_STORE_TAG_V2 and Fernet is not None:
        try:
            token = str(record.get("token") or "").encode("ascii")
            plain = Fernet(_fernet_key()).decrypt(token)
            out = json.loads(plain.decode("utf-8"))
            return out if isinstance(out, dict) else None
        except (InvalidToken, Exception):
            return None
    if record.get("__cred_store") != CRED_STORE_TAG:
        return None
    try:
        nonce_b64 = record.get("nonce", "")
        mac_b64 = record.get("mac", "")
        blob_b64 = record.get("blob", "")
        nonce = base64.urlsafe_b64decode(nonce_b64.encode("ascii", errors="ignore"))
        mac = base64.urlsafe_b64decode(mac_b64.encode("ascii", errors="ignore"))
        blob = base64.urlsafe_b64decode(blob_b64.encode("ascii", errors="ignore"))
    except Exception:
        return None
    if len(nonce) < 8 or len(blob) < 1:
        return None
    key = _credential_master_key()
    mask = _cred_xor_mask(key, nonce, len(blob))
    plain = bytes(a ^ b for a, b in zip(blob, mask))
    expected = hmac.new(key, nonce + plain, hashlib.sha256).digest()
    if not hmac.compare_digest(mac, expected):
        return None
    try:
        out = json.loads(plain.decode("utf-8"))
    except Exception:
        return None
    return out if isinstance(out, dict) else None


def _load_credentials():
    path = Path(CREDS_FILE)
    if not path.exists():
        return None
    try:
        raw_text = path.read_text(encoding="utf-8")
    except Exception:
        return None
    if not raw_text:
        return None
    try:
        parsed = json.loads(raw_text)
    except Exception:
        return None
    if isinstance(parsed, dict):
        decrypted = _decrypt_creds(parsed)
        if isinstance(decrypted, dict):
            return decrypted
        if "__cred_store" not in parsed:
            return parsed
    return None


def _save_credentials(payload):
    enc = _encrypt_creds(payload)
    Path(CREDS_FILE).write_text(json.dumps(enc, indent=4, ensure_ascii=False), encoding="utf-8")
    if os.name != "nt":
        try:
            os.chmod(CREDS_FILE, 0o600)
        except Exception:
            pass


SENSITIVE_FIELD_NEEDLES = (
    "authorization", "cookie", "session", "sessionid", "token", "secret",
    "password", "passwd", "api_key", "apikey", "api hash", "api_hash",
    "tg_hash", "tg_session", "shodan_key", "sid", "tiktok_sid", "phone"
)


def redact_sensitive(value):
    if isinstance(value, dict):
        out = {}
        for k, v in value.items():
            lk = str(k).lower()
            if any(n in lk for n in SENSITIVE_FIELD_NEEDLES):
                out[k] = "[REDACTED]"
            else:
                out[k] = redact_sensitive(v)
        return out
    if isinstance(value, list):
        return [redact_sensitive(v) for v in value]
    if isinstance(value, str):
        if re.search(r"(sessionid|api[_ -]?hash|authorization|bearer|token|password|cookie)", value, re.I):
            return "[REDACTED]"
    return value


def safe_json_dump(payload, fp, **kwargs):
    json.dump(redact_sensitive(payload), fp, **kwargs)


def _store_tg_session(session_value):
    value = str(session_value or "").strip()
    if not value:
        return
    keyring.set_password(TG_SESSION_KEYRING_SERVICE, TG_SESSION_KEYRING_USER, value)


def _load_tg_session():
    try:
        return keyring.get_password(TG_SESSION_KEYRING_SERVICE, TG_SESSION_KEYRING_USER) or ""
    except Exception:
        return ""


def _clear_tg_session():
    try:
        keyring.delete_password(TG_SESSION_KEYRING_SERVICE, TG_SESSION_KEYRING_USER)
    except Exception:
        pass


def client_ip():
    return request.headers.get("X-Forwarded-For", request.remote_addr or "local").split(",")[0].strip()


def rate_limited(scope, limit=20, window=60):
    now = time.time()
    key = f"{scope}:{client_ip()}"
    with RATE_LIMIT_LOCK:
        bucket = [ts for ts in RATE_LIMIT_BUCKETS.get(key, []) if now - ts < window]
        if len(bucket) >= limit:
            RATE_LIMIT_BUCKETS[key] = bucket
            return True
        bucket.append(now)
        RATE_LIMIT_BUCKETS[key] = bucket
        return False


def require_sensitive_request(scope, limit=20, window=60):
    if rate_limited(scope, limit=limit, window=window):
        return jsonify({"status": "error", "message": "Troppe richieste. Riprova tra poco."}), 429
    csrf = request.headers.get("X-CSRF-Token", "")
    expected = flask_session.get("csrf_token", "")
    if not flask_session.get("admin_authenticated"):
        return jsonify({"status": "error", "message": "Sessione amministratore non valida."}), 401
    if not expected or not hmac.compare_digest(csrf, expected):
        return jsonify({"status": "error", "message": "CSRF token non valido."}), 403
    return None


def require_authenticated_download(scope, limit=40, window=60):
    if rate_limited(scope, limit=limit, window=window):
        return "Troppe richieste. Riprova tra poco.", 429
    if not flask_session.get("admin_authenticated"):
        return "Sessione amministratore non valida.", 401
    return None


def public_error(message="Operazione non riuscita.", status=400):
    return jsonify({"status": "error", "message": message}), status


def ensure_admin_browser_session():
    flask_session["admin_authenticated"] = True
    if not flask_session.get("csrf_token"):
        flask_session["csrf_token"] = secrets.token_urlsafe(32)
    return flask_session["csrf_token"]


