            ffmpeg_bin = _resolve_ffmpeg_bin()
            if not ffmpeg_bin:
                return jsonify({"error": "ffmpeg non disponibile (ne' PATH ne' fallback imageio-ffmpeg)."}), 500
            target_w = int(_safe_float(video_resize_width, 1280, min_v=64))
            target_h = int(_safe_float(video_resize_height, 720, min_v=64))
            pad = (str(video_pad_color or "black") or "black").strip().replace(" ", "")
            crop_mode = (video_resize_crop_mode or "fit").strip().lower()
            if crop_mode not in {"fit", "cover", "pad"}:
                crop_mode = "fit"
            out_path = media_dir / f"{job_id}_resize_pad.mp4"
            if crop_mode == "cover":
                vf = (
                    f"scale={target_w}:{target_h}:force_original_aspect_ratio=increase,"
                    f"crop={target_w}:{target_h}"
                )
            elif crop_mode == "pad":
                vf = (
                    f"scale={target_w}:{target_h}:force_original_aspect_ratio=increase,"
                    f"pad={target_w}:{target_h}:(ow-iw)/2:(oh-ih)/2:{pad}"
                )
            else:
                vf = (
                    f"scale={target_w}:{target_h}:force_original_aspect_ratio=decrease,"
                    f"pad={target_w}:{target_h}:(ow-iw)/2:(oh-ih)/2:{pad}"
                )
            proc = _run_ffmpeg([
                ffmpeg_bin,
                "-y",
                "-i", str(src_path),
                "-vf", vf,
                "-c:v", "libx264",
                "-preset", "veryfast",
                "-crf", "20",
                "-c:a", "copy",
                str(out_path)
            ], timeout=420)
