def _parse_semver(v):
    raw = str(v or "").strip().lower().lstrip("v")
    parts = re.findall(r"\d+", raw)
    if not parts:
        return (0, 0, 0)
    nums = [int(x) for x in parts[:3]]
    while len(nums) < 3:
        nums.append(0)
    return tuple(nums)

def _resolve_github_repo_slug():
    env_slug = (os.environ.get("INTELOSINT_GITHUB_REPO") or "").strip()
    if env_slug:
        return env_slug
    try:
        p = subprocess.run(
            ["git", "remote", "get-url", "origin"],
            cwd=str(Path(__file__).resolve().parent),
            capture_output=True,
            text=True,
            timeout=8
        )
        if p.returncode != 0:
            return ""
        url = (p.stdout or "").strip()
        m = re.search(r"github\.com[:/]+([^/]+/[^/.]+)", url, flags=re.IGNORECASE)
        return m.group(1) if m else ""
    except Exception:
        return ""

@app.route('/api/update/check', methods=['POST'])
def update_check():
    try:
        slug = _resolve_github_repo_slug()
        if not slug:
            return jsonify({"error": "Repository GitHub non configurato. Imposta INTELOSINT_GITHUB_REPO=owner/repo."}), 400
        url = f"https://api.github.com/repos/{slug}/releases/latest"
        r = requests.get(url, timeout=10)
        if r.status_code != 200:
            return jsonify({"error": f"GitHub API HTTP {r.status_code}", "repo": slug}), 502
        j = r.json() if isinstance(r.json(), dict) else {}
        latest = (j.get("tag_name") or j.get("name") or "").strip() or "v0.0.0"
        local_v = f"v{APP_VERSION}"
        update_available = _parse_semver(latest) > _parse_semver(local_v)
        return jsonify({
            "repo": slug,
            "local_version": local_v,
            "latest_version": latest,
            "update_available": update_available,
            "release_url": j.get("html_url", "")
        })
    except Exception as e:
        return jsonify({"error": f"Errore verifica aggiornamenti: {e}"}), 500

if __name__ == '__main__':
    threading.Thread(target=lambda: (time.sleep(2), webbrowser.open(f"http://127.0.0.1:{PORT_NUMBER}/"))).start()
    app.run(port=PORT_NUMBER)
